#!/usr/bin/env python3
# -*- coding: utf-8 -*-
#
# Generate the fullwidth codepoint table used by src/unicode.c:
#
#   src/fullwidth.inc  - fullwidth[]: codepoints that occupy two terminal
#                        columns (East Asian Wide/Fullwidth).
#
# Emitted as a C {lo,hi} initializer list, #included into the array body in
# src/unicode.c. Derived from the Python build's Unicode database, so
# regenerate after a Unicode bump:
#
#     python3 scripts/gen-wcwidth.py
#
# Run with no arguments to (re)write the table in place next to unicode.c.
# The generated file is checked in, so an ordinary build never needs this.

import os
import sys
import unicodedata as u

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.normpath(os.path.join(HERE, "..", "src"))

# The table stops here: libvterm only ever asks about the BMP and the first
# supplementary planes, and the ranges above are all unassigned or narrow.
MAX_CP = 0x20000


def wide_codepoints():
    return {cp for cp in range(MAX_CP)
            if u.east_asian_width(chr(cp)) in ("W", "F")}


def to_ranges(cps):
    ranges = []
    it = sorted(cps)
    start = prev = it[0]
    for cp in it[1:]:
        if cp == prev + 1:
            prev = cp
        else:
            ranges.append((start, prev))
            start = prev = cp
    ranges.append((start, prev))
    return ranges


def emit(path, array, ranges):
    with open(path, "w") as f:
        f.write("/* %s: generated by scripts/gen-wcwidth.py from Unicode %s. */\n"
                "/* Do not edit by hand; rerun the script after a Unicode bump. */\n"
                % (array, u.unidata_version))
        for lo, hi in ranges:
            f.write("  { %#04x, %#04x },\n" % (lo, hi))
    print("wrote %s (%d ranges)" % (path, len(ranges)), file=sys.stderr)


def main():
    emit(os.path.join(SRC, "fullwidth.inc"),
         "fullwidth[]", to_ranges(wide_codepoints()))


if __name__ == "__main__":
    main()
